decisions=[]
for i,x in enumerate(base['changes']):
 d=copy.deepcopy(x);d['final']=d.pop('reading');d['crops']=[f'readers/018/C/'+d.pop('crop')]
 if i==0:rr={'A':'around here','B':'around here','C':d['final']}; ev='The main reader sees only a narrow d-to-h gap, much smaller than the preceding word gap. The joined form is favoured, but a compressed space is possible. C’s explicit uncertainty is adopted against the unmarked space in A/B and witness C.'
 elif i==1:rr={'A':d['c'],'B':d['c'],'C':d['final']};ev='The main reader sees a compact angular opening mass with a side projection and no separate pair. Its contour cannot distinguish a single stroke from fused doubles. The separate closing pair is certain; the new opening doubt is adopted.'
 elif i==2:rr={'A':"'",'B':d['c'],'C':'’'};ev='The main reader sees one narrow upright closing stroke with a small shoulder, not a second parallel leg. The next lower dot belongs to the i of is. A/C’s single closing quotation is adopted; the curly versus straight apostrophe encoding is not a separate reading difference.'
 else:rr={'A':r"\unsure{`|``}last but not least''",'B':d['c'],'C':d['final']};ev='The main reader sees a single angular upright mass with a side shoulder, matching the ambiguous first opening mark in this line. It does not securely establish one versus fused-double strokes. A/C’s opening uncertainty is adopted; the two closing strokes remain clear.'
 d['readers']=rr;d['evidence']=ev;d['kind']='other';decisions.append(d)
def add(id,place,c,final,readers,evidence,crop,diff=True,confidence='medium'):
 decisions.append(dict(id=id,place=place,c=c,h=None,final=final,readers=readers,evidence=evidence,crops=[crop],diff_c=diff,diff_h=False,kind='other',marked_in_H=False,confidence=confidence))
add('018-compositum-case','p66 line 13, first proposed Latin form','compositum',r'\unsure{Compositum|compositum}',{'A':'compositum','B':r'\unsure{Compositum|compositum}','C':'compositum'},'The main reader sees an initial open curve rising to ascender height, substantially above the following o. Capital C is favoured, but the sloping line and enlarged word-initial form leave lowercase possible. B’s explicit case doubt is adopted. The rest of the letter sequence is secure.','readers/018/B/crops/04-compositum.jpg')
add('018-second-Latin-case','p66 line 13, second Latin after My','Latin',r'\unsure{Latin|latin}',{r:'Latin in text; Latin/latin acknowledged as uncertain in report' for r in 'ABC'},'Both inspected initials have tall stems and low turns. Their case remains uncertain. All three readers report that uncertainty for both occurrences but mark only the first, following C’s shorthand. The main reader marks the second occurrence in place as required; no recurrence is treated as certain merely because its doubt appeared earlier.','readers/018/C/crops/06.jpg')
add('018-avec-retained','Opening aside, after avec',r'avec\unsure{,|-}',r'avec\unsure{,|-}',{'A':'avec-','B':r'avec\unsure{,|-}','C':r'avec\unsure{,|-}'},'The main reader sees a short oblique low stroke without a decisive head/tail or a long horizontal shaft. A favours a dash; B/C retain the ambiguity. The crop does not securely eliminate either punctuation reading, so witness C is retained.','readers/018/A/crops/02_avec_punctuation.jpg',False,'low')
add('018-aside-close-retained','Opening aside, after exclamation before parenthesis',r"!\unsure{..|''})",r"!\unsure{..|''})",{'A':r"!\unsure{..|''})",'B':"!'')",'C':r"!\unsure{..|''})"},'The main reader sees two compact angular marks descending diagonally above the exclamation’s low dot. Their height favours B’s quotation reading, but their shapes and sloping placement do not securely exclude dots. A/C’s retained uncertainty is adopted. The weaker cluster after the parenthesis also remains uncertain.','readers/018/C/crops/04.jpg',False,'low')
add('018-goodenough-retained','p66 line 13, dictionary qualification',r'\unsure{goodenough|good enough}',r'\unsure{goodenough|good enough}',{'A':'goodenough','B':r'\unsure{goodenough|good enough}','C':r'\unsure{goodenough|good enough}'},'The main reader sees a narrow but real d-to-e gap. Joining is favoured by its small size, as A observes, but this hand also uses compressed word gaps. B/C’s uncertainty is retained, consistently with the newly marked aroundhere/around here locus. Intended normal spelling is not used to decide the space.','readers/018/A/crops/06_goodenough.jpg',False)
cd=doubt_decisions(base,18,'C')
