cd[15]['evidence']+=' Main-reader case decision is recorded above, from readers/018/B/crops/04-compositum.jpg.'
doubts=copy.deepcopy(base['remaining_doubts'])
lat=next(d for d in doubts if 'both occurrences of Latin' in d['place']);lat['place']='p66, first occurrence of Latin';lat['reading']=r'\unsure{Latin|latin}'
